package publish
import "testing"
func TestPublicationRevalidation(t *testing.T){live:=Observation{Head:"h",Target:"t",PolicyDigest:"p",ChecksPass:true};for _,tc:=range []struct{name string;r Request;l Observation;want bool}{{"shadow",Request{Mode:"shadow",ReviewedHead:"h",ReviewedTarget:"t",PolicyDigest:"p",Eligible:true},live,false},{"submit",Request{Mode:"submit",ReviewedHead:"h",ReviewedTarget:"t",PolicyDigest:"p",Eligible:true},live,true},{"stale head",Request{Mode:"submit",ReviewedHead:"old",ReviewedTarget:"t",PolicyDigest:"p",Eligible:true},live,false},{"stale target",Request{Mode:"submit",ReviewedHead:"h",ReviewedTarget:"old",PolicyDigest:"p",Eligible:true},live,false},{"injected policy",Request{Mode:"submit",ReviewedHead:"h",ReviewedTarget:"t",PolicyDigest:"other",Eligible:true},live,false},{"checks fail",Request{Mode:"submit",ReviewedHead:"h",ReviewedTarget:"t",PolicyDigest:"p",Eligible:true},Observation{Head:"h",Target:"t",PolicyDigest:"p"},false},{"ineligible",Request{Mode:"submit",ReviewedHead:"h",ReviewedTarget:"t",PolicyDigest:"p"},live,false}}{t.Run(tc.name,func(t *testing.T){d,e:=Gate(tc.r,tc.l);if e!=nil||d.Approve!=tc.want{t.Fatalf("%#v %v",d,e)};if !d.Approve&&d.Reason==""{t.Fatal("missing withholding reason")}})}}
func TestOnlyOwnedCommentsSelected(t *testing.T){cs:=[]Comment{{ID:"human",Body:"<!-- reviewd -->",Owned:false},{ID:"ours",Body:"<!-- reviewd --> report",Owned:true}};id,e:=OwnedComment(cs,"<!-- reviewd -->");if e!=nil||id!="ours"{t.Fatalf("%s %v",id,e)};cs=append(cs,Comment{ID:"ambiguous",Body:"<!-- reviewd -->",Owned:true});if _,e=OwnedComment(cs,"<!-- reviewd -->");e==nil{t.Fatal("ambiguous publication not reconciled")}}
